window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]=window.__LIBQ["the-gioi-hoan-my"]["q06"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]["map"]={"updatedAt":"2026-07-22","count":131,"nodes":[{"id":"dong-phu-phong-an-bat-lao-son","name":"Động phủ phong ấn của Bất Lão Sơn","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Một động phủ có cấm chế tại Bất Lão Sơn, bên trong cất giữ nhiều thần liệu và thần vật.","detail":"Tiểu Tháp lợi dụng lúc Bất Lão Thiên Tôn đang giao chiến để phá cấm chế và cửa đá của động phủ. Bên trong là kho bảo vật có bảo quang rực rỡ cùng lượng lớn thần liệu và thần vật.","theLucLienQuan":["Bất Lão Sơn"],"nguon":["@c0501"]},{"id":"bao-kho-bat-lao-son","name":"Bảo khố Bất Lão sơn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Bảo khố tích lũy tài vật từ thời thượng cổ của Bất Lão sơn.","detail":"Nơi cất giữ tàn cốt trắng bóng liên quan đến Nguyên thủy chân giải, đất Hỗn độn, Thái dương thạch và nhiều vật liệu quý. Tiểu Tháp, Đả Thần Thạch và Thạch Hạo đã thu lấy toàn bộ tài nguyên có giá trị tại đây.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0502"]},{"id":"vuon-thuoc-bat-lao-son","name":"Vườn thuốc Bất Lão sơn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Khu trồng linh dược, bảo dược và thánh dược của Bất Lão sơn.","detail":"Phần lớn cây cỏ trong vườn đã héo úa sau khi sinh linh bất diệt hấp thu nguyên khí thiên địa và tinh hoa của chúng. Khu vực trồng thánh dược còn được đại trận che giấu để ngăn linh khí thoát ra ngoài.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0502"]},{"id":"ho-niet-ban","name":"Hồ Niết bàn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Những hồ bảo dịch thuộc Bất Lão sơn, vốn có thể dùng để tiến hành Niết bàn.","detail":"Các hồ đã bị sinh linh bất diệt hút cạn phần lớn tinh khí và trở nên khô cạn trước khi Thạch Hạo có thể sử dụng bảo dịch bên trong.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0502"]},{"id":"khu-vuc-trong-cay-ngu-nguyen","name":"Khu vực trồng cây Ngũ nguyên","cn":"","capDo":"khac","parentId":"vuon-thuoc-bat-lao-son","blurb":"Không gian bí mật trong vườn thuốc Bất Lão sơn, được dùng để trồng cây Ngũ nguyên.","detail":"Khu vực này được trận pháp thần linh che giấu và ngăn linh khí tiết ra. Bên trong có hồ linh dịch đã khô cạn cùng bốn chậu đá năm màu chứa đất Ngũ hành, trong đó cây Ngũ nguyên gần chết vẫn còn sống.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0502"]},{"id":"bao-gioi-thai-co","name":"Bảo giới thái cổ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một thế giới bí ẩn xuất thế tại Huyền vực, ẩn chứa cơ duyên lớn và thu hút nhiều cường giả tiến vào.","detail":"Sinh linh bất diệt, Tiểu Tháp và các bá chủ thượng giới lần lượt tiến vào bảo giới để tranh đoạt cơ duyên. Thạch Hạo gặp Lam Vũ, Thuỷ Nguyệt và Hồng Hoàng tại đây, đồng thời cảm ứng được dao động quen thuộc của Liễu Thần; sự xuất hiện của bảo giới có một phần liên quan tới Liễu Thần.","theLucLienQuan":[],"nguon":["@c0502"]},{"id":"noi-sau-nhat-bao-gioi-thai-co","name":"Nơi sâu nhất trong Bảo giới thái cổ","cn":"","capDo":"khac","parentId":"bao-gioi-thai-co","blurb":"Khu vực sâu nhất của Bảo giới thái cổ, nơi ẩn chứa cấm chế và cơ duyên lớn.","detail":"Các cường giả vừa giao chiến vừa dùng thần thức dò xét khu vực này sau khi cấm chế phát ra dao động kinh người. Liễu Thần đã tiến vào bên trong cấm chế trước những người khác.","theLucLienQuan":[],"nguon":["@c0503"]},{"id":"tieu-the-gioi-hon-don","name":"Tiểu thế giới hỗn độn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thế giới từng thai nghén Sinh linh bất diệt trong hơn trăm vạn năm.","detail":"Sinh linh bất diệt vốn sinh ra ở hậu thiên nhưng được đưa vào tiểu thế giới này để thai nghén, nhờ đó thu được dấu ấn tiên thiên. Tiểu thế giới hỗn độn tan vỡ khi sinh linh ấy ra đời.","theLucLienQuan":[],"nguon":["@c0506"]},{"id":"canh-cua-nguyen-thuy","name":"Cánh cửa nguyên thủy","cn":"","capDo":"khac","parentId":"bao-gioi-thai-co","blurb":"Cánh cửa sinh ra cùng hỗn độn, có khả năng tái hiện trong Bảo giới thái cổ.","detail":"Cánh cửa chỉ từng xuất hiện vài lần, có liên hệ với chiến dịch thái cổ và thần chiến thượng cổ. Những người từng tiến vào đều biến mất, chỉ có máu chảy ra; Liễu Thần tiến sâu vào Bảo giới để kiểm tra trước khi quyết định có bước qua hay không.","theLucLienQuan":[],"nguon":["@c0506"]},{"id":"gioi-hon-don","name":"Giới hỗn độn","cn":"","capDo":"vuc","parentId":"bao-gioi-thai-co","blurb":"Vùng hỗn độn nằm tại nơi sâu nhất của Bảo giới thái cổ, vượt quá khả năng tiến vào của Thạch Hạo lúc này.","detail":"Nơi sông núi của Bảo giới tiếp giáp biển hỗn độn, có pháp tắc và ký hiệu dày đặc cùng nguyên khí hỗn độn. Liễu Thần, Tiểu Tháp và Sinh linh bất diệt tiến vào khu vực này, còn Thạch Hạo bị truyền tống ra xa vì tu vi chưa đủ.","theLucLienQuan":[],"nguon":["@c0506"]},{"id":"tam-vuc","name":"Tám vực","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực bị gọi là lao tù mà Ngũ Hành sơn đã thoát khỏi để tới thượng giới.","detail":"Ngũ Hành sơn hóa thành khí bản nguyên, đi qua điện đồng Bất Lão sơn và rời khỏi Tám vực bằng con đường thông lên thượng giới.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0506"]},{"id":"thanh-tri-hoa-nha","name":"Thành trì Hỏa nha","cn":"","capDo":"thanh","parentId":"bao-gioi-thai-co","blurb":"Thành trì của tộc Hỏa nha nằm giữa vùng có nhiều núi lửa, gần tám hồ Địa hỏa dịch.","detail":"Nơi đây có Hỏa nha đầu chim thân người sinh sống, quân canh mặc giáp đen hoặc vàng, cùng nhiều vương giả và Tôn giả bảo vệ bộ tộc.","theLucLienQuan":["Tộc Hỏa nha"],"nguon":["@c0507"]},{"id":"dong-phu-thach-nhu","name":"Động phủ thạch nhũ","cn":"","capDo":"khac","parentId":"bao-gioi-thai-co","blurb":"Một động phủ bỏ hoang chứa ao thạch nhũ tích lũy qua thời gian dài.","detail":"Thạch Hạo tìm thấy nơi này và hấp thu tinh hoa trong ao thạch nhũ để tẩm bổ thân thể cùng Chí tôn cốt.","theLucLienQuan":[],"nguon":["@c0507"]},{"id":"to-dia-kim-o","name":"Tổ địa Kim Ô","cn":"","capDo":"khac","parentId":"bao-gioi-thai-co","blurb":"Thần thổ thái cổ phía sau thành cổ Kim Ô, từng bị một trận pháp cổ phong ấn.","detail":"Khi trận pháp giải thể, tổ địa tái xuất cùng biển dung nham rộng vô tận và những dấu vết liên quan đến di tích thần thoại khởi nguyên.","theLucLienQuan":["Tộc Kim Ô"],"nguon":["@c0507"]},{"id":"bien-kim-o","name":"Biển Kim Ô","cn":"","capDo":"khac","parentId":"to-dia-kim-o","blurb":"Biển dung nham vô biên trong tổ địa Kim Ô, có nhiệt lực đủ làm Tôn giả bị thương và quy tắc cấm phi hành.","detail":"Trên biển xuất hiện một chiếc thuyền cổ; sâu bên trong còn hiện ra dị tượng Thần thụ Thái dương, nhật nguyệt tinh thần và một tòa cung điện tỏa hào quang bất hủ.","theLucLienQuan":["Tộc Kim Ô"],"nguon":["@c0507"]},{"id":"than-thu-thai-duong","name":"Thần thụ Thái Dương","cn":null,"capDo":"khac","parentId":"bien-dung-nham-do-dam","blurb":"Cây bảo thụ hoàng kim nằm sâu giữa biển dung nham, tái hiện sau khi phong ấn mở và trở thành mục tiêu tranh đoạt của nhiều Tôn giả.","detail":"Thần thụ được nhật nguyệt và tinh thần vờn quanh, trên tán có một ngôi điện thần bí. Khi nhìn gần, cây chỉ cao khoảng một thước, mỗi chiếc lá nâng đỡ một ngôi sao; sinh linh tiếp cận sẽ dần bị thu nhỏ như hạt bụi bởi quy tắc không gian đặc biệt quanh cây.","theLucLienQuan":["Tộc Kim ô"],"nguon":["@c0508"]},{"id":"bien-dung-nham-do-dam","name":"Biển dung nham đỏ đậm","cn":null,"capDo":"vuc","parentId":"bao-gioi-thai-co","blurb":"Đại dương dung nham mênh mông bao quanh Thần thụ Thái Dương, rộng đến mức đoàn người phải di chuyển cực nhanh suốt năm ngày mới tới đích.","detail":"Dung nham có nhiệt độ đủ nung chảy pháp khí thông thường và đốt cháy rễ của cổ thụ Thiết huyết. Trong biển còn có các cổ thuyền chở tử thi bị nguyền rủa cùng vô số bạch cốt từ chiến trận thái cổ.","theLucLienQuan":["Tộc Kim ô"],"nguon":["@c0508"]},{"id":"ngoi-dien-tren-tan-than-thu","name":"Ngôi điện trên tán thần thụ","cn":null,"capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Ngôi điện thần bí tọa lạc trên tán cây hoàng kim giữa biển dung nham.","detail":"Từ xa, điện hiện lên khổng lồ giữa cảnh tượng nhật nguyệt và tinh thần vờn quanh thần thụ. Khi đến gần hoàng kim thụ, mọi người thấy cổ điện chỉ cao bằng lòng bàn tay và liên tục phun nuốt khí hỗn độn.","theLucLienQuan":[],"nguon":["@c0508"]},{"id":"khu-vuc-cam-khong","name":"Khu vực cấm không","cn":null,"capDo":"vuc","parentId":"bien-dung-nham-do-dam","blurb":"Vùng không gian trên biển lửa có quy tắc hạn chế năng lực xuyên không.","detail":"Dù khu vực này cấm không, cầu đá của Tuyên Minh vẫn hóa thành một con đường nối tới nơi sâu trong biển lửa, đưa ba bảo thuyền xuyên qua hư không và thoát khỏi vòng vây của thuyền ma cùng bạch cốt.","theLucLienQuan":[],"nguon":["@c0508"]},{"id":"khu-vuc-hoang-kim-thu","name":"Khu vực hoàng kim thụ","cn":null,"capDo":"vuc","parentId":"bien-dung-nham-do-dam","blurb":"Khu vực nằm sâu trong biển đỏ, nơi hoàng kim thụ cắm rễ và tỏa ra bảo quang cùng khí lành.","detail":"Nơi đây có dị tượng ngân hà vờn quanh cây, tinh tú được nâng đỡ trên từng chiếc lá và khí hỗn độn do cổ điện trên tán cây phun nuốt. Không gian quanh hoàng kim thụ khiến sinh linh tiến lại gần bị thu nhỏ dần.","theLucLienQuan":["Tộc Kim ô"],"nguon":["@c0508"]},{"id":"cam-che-hoang-kim-cay-thai-duong","name":"Cấm chế hoàng kim của cây Thái Dương","cn":"","capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Màn sáng hoàng kim ngăn mọi sinh linh chạm tới thần thụ.","detail":"Cấm chế mang sức mạnh đại thế giới, cần dùng sức mạnh của tiểu thế giới làm chất xúc tác mới có thể mở đường đi qua.","theLucLienQuan":["Đoàn thiên tài thượng giới","Tôn giả Bảo giới thái cổ"],"nguon":["@c0509"]},{"id":"bien-dia-hoa-dich-duoi-re-hoang-kim","name":"Biển địa hỏa dịch dưới rễ cây Hoàng kim","cn":"","capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Hải dương huyết thanh đỏ đậm nằm dưới rễ cây Hoàng kim, chứa lượng tinh hoa dồi dào.","detail":"Địa hỏa dịch không làm Thạch Hạo bị thương mà khiến Chí tôn cốt nơi ngực thức tỉnh và hấp thu tinh hoa. Ở nơi sâu hơn còn có linh dịch mang thần năng mạnh mẽ.","theLucLienQuan":[],"nguon":["@c0509"]},{"id":"he-re-hoang-kim-thu","name":"Hệ rễ Hoàng kim thụ","cn":"","capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Hệ rễ chính và rễ con vô cùng dài rộng, kéo sâu hàng chục dặm dưới biển địa hỏa dịch.","detail":"Một số rễ hoàng kim có thể luyện hóa địa hỏa dịch thành lượng nhỏ tinh hoa gần đạt thần dịch, giúp Thạch Hạo thúc đẩy quá trình tái sinh Chí tôn cốt.","theLucLienQuan":[],"nguon":["@c0510"]},{"id":"la-cay-hoang-kim","name":"Lá cây hoàng kim","cn":"","capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Những chiếc lá cực lớn mọc trên thần thụ Thái dương, mỗi lá nâng đỡ một ngôi sao mờ đang thai nghén.","detail":"Thạch Hạo chọn một lá cây làm nơi bế quan, hấp thu bản nguyên của ngôi sao bên cạnh và khắc phù văn Chí tôn cốt vào máu thịt, phủ tạng.","theLucLienQuan":[],"nguon":["@c0510"]},{"id":"chien-truong-co-dai-tren-hoang-kim-thu","name":"Chiến trường cổ đại trên Hoàng kim thụ","cn":null,"capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Chiến trường cổ nằm giữa thân, cành và lá của Hoàng kim thụ, rải rác hài cốt từ những cuộc giao tranh trước đây.","detail":"Hươu năm màu phục kích Thạch Hạo tại khu vực này nhưng bị phù văn hộ thể của đối phương phá hủy pháp khí, bảo cụ rồi thiêu chết.","theLucLienQuan":[],"nguon":["@c0511"]},{"id":"co-dien-hon-don","name":"Cổ điện Hỗn độn","cn":null,"capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Cổ điện nằm gần đỉnh cao nhất của Hoàng kim thụ, phía sau vùng sương mù hoàng kim.","detail":"Thạch Hạo nhìn thấy cổ điện sau khi vượt qua chiến trường cổ đại và tiếp tục tiến lên phần cao nhất của thần thụ.","theLucLienQuan":[],"nguon":["@c0511"]},{"id":"nui-the-gioi","name":"Núi thế giới","cn":null,"capDo":"khac","parentId":"than-thu-thai-duong","blurb":"Ngọn thần sơn ẩn hiện trong hỗn độn, tràn đầy sinh cơ và do Thế giới thụ thai nghén.","detail":"Một nhóm người đang giao chiến trên Núi thế giới khi Thạch Hạo phát hiện nơi này. Đả Thần Thạch nhận ra nguồn gốc của ngọn núi và thúc giục tiến tới tranh đoạt tạo hóa.","theLucLienQuan":[],"nguon":["@c0511"]},{"id":"hoang-kim-thu","name":"Hoàng kim thụ","cn":null,"capDo":"khac","parentId":null,"blurb":"Cổ thụ có màn sáng bảo vệ và cành cây vàng dẫn vào Cung điện Hỗn Độn.","detail":"Thạch Hạo từng dùng Thế giới hộp báu phá tan màn sáng của Hoàng kim thụ. Khi hoa hoàng kim bay vào Cung điện Hỗn Độn, cành cây vàng nối với hoa trở thành đường dẫn giúp mọi người vượt qua phù văn ngoài cửa.","theLucLienQuan":[],"nguon":["@c0514"]},{"id":"dao-dai-sau-trong-co-dien-hon-don","name":"Đạo đài sâu trong cổ điện","cn":null,"capDo":"khac","parentId":"co-dien-hon-don","blurb":"Đạo đài nằm sâu trong Cung điện Hỗn Độn, có các bồ đoàn và vang lên thần âm đại đạo.","detail":"Cô gái tóc vàng trong quả trứng xuất hiện trên đạo đài giữa những phù văn, tựa như đang nghe giảng đạo. Gần đó có bàn đá và giá sách đá đặt hai quyển cốt thư tỏa khí hỗn độn.","theLucLienQuan":[],"nguon":["@c0514"]},{"id":"ban-da-va-gia-sach-trong-co-dien","name":"Bàn đá và giá sách trong cổ điện","cn":"","capDo":"khac","parentId":"co-dien-hon-don","blurb":"Hai vị trí đặt cốt thư hỗn độn trong Cổ điện Hỗn độn.","detail":"Bàn đá và giá sách là nơi đặt hai bộ cốt thư tỏa khí hỗn độn. Lực phản chấn và khí hỗn độn bao quanh khiến những người tham gia tranh đoạt khó tiếp cận.","theLucLienQuan":[],"nguon":["@c0515"]},{"id":"vung-nui-hon-don","name":"Vùng núi hỗn độn","cn":"","capDo":"khac","parentId":null,"blurb":"Một vùng đồi núi thấp được trận pháp hỗn độn của Tiểu Tháp bảo vệ, là nơi cha mẹ Thạch Hạo trú ẩn an toàn.","detail":"Vùng núi có cây cỏ, linh hồ và tinh khí dồi dào. Tiểu Tháp dùng pháp kỳ cùng khí hỗn độn bố trí trận pháp bao phủ nơi này, đến khi trở về mới thu hồi trận pháp để Thạch Hạo đoàn tụ với gia đình.","theLucLienQuan":[],"nguon":["@c0520"]},{"id":"bien-hon-don","name":"Biển hỗn độn","cn":"","capDo":"khac","parentId":null,"blurb":"Biển hỗn độn vô tận nơi Tiểu Tháp và Liễu Thần truy tìm cánh cửa nguyên thủy.","detail":"Tiểu Tháp cùng Liễu Thần tiến sâu vào biển hỗn độn, vừa đi vừa tìm kiếm nhưng vẫn khó đuổi kịp cánh cửa nguyên thủy.","theLucLienQuan":[],"nguon":["@c0520"]},{"id":"bien-y-thuc-cua-nguyet-thien","name":"Biển ý thức của Nguyệt Thiền","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian thần thức của Nguyệt Thiền, nơi Thạch Hạo và Ma nữ xâm nhập để trấn áp tiềm thức của nàng.","detail":"Biển ý thức trong suốt, có mây mù, lầu quỳnh điện ngọc và một ngọc cung chứa tiềm thức mang khí tức như thần chỉ. Nơi đây trở thành chiến trường thần hồn giữa Nguyệt Thiền với Thạch Hạo và Ma nữ; Trấn thần châu được dùng để cố định không gian, còn Nhân hoàng ấn bảo vệ Thạch Hạo bằng long khí.","theLucLienQuan":[],"nguon":["@c0522"]},{"id":"trung-uong-thien-cung","name":"Trung ương thiên cung","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Tần Di Ninh đối đáp với Nguyệt Thiền và quyết định tổ chức hôn lễ giữa nàng với Thạch Hạo ngay trong đêm.","detail":"Tại đây, Tần Di Ninh gọi Bằng Cửu tới, ra lệnh chuẩn bị tiệc cưới và sau đó cho phép tổ chức hôn lễ đơn giản trong phạm vi gia đình.","theLucLienQuan":[],"nguon":["@c0525"]},{"id":"phong-tan-hon-hoang-cung-thach-quoc","name":"Phòng tân hôn","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Cung điện yên tĩnh trong Hoàng cung Thạch Quốc, được dùng làm phòng tân hôn của Thạch Hạo và Nguyệt Thiền.","detail":"Nơi này được trang hoàng bằng nến và lồng đèn đỏ. Sau hôn lễ bí mật, Thạch Hạo đưa Nguyệt Thiền tới đây, trêu chọc nàng về chuyện sinh con và nghe nàng đưa ra điều kiện bắt Ma nữ vào hoàng cung.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0526"]},{"id":"tang-may-phia-tren-hoang-cung","name":"Tầng mây phía trên hoàng cung","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Chiến trường trên không nơi Thạch Hạo giao chiến trực diện với chủ thân Nguyệt Thiền.","detail":"Chủ thân Nguyệt Thiền bố trí một đại trận khổng lồ tại đây để triệu hoán thiên thạch và núi lớn công kích Hoàng cung Thạch quốc. Thạch Hạo cõng thứ thân Nguyệt Thiền vượt qua mưa thiên thạch, tiến lên tầng mây nghênh chiến.","theLucLienQuan":[],"nguon":["@c0529"]},{"id":"vung-troi-phia-tren-hoang-cung","name":"Vùng trời phía trên hoàng cung","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường trên không nơi Thạch Hạo giao chiến với chủ thân Nguyệt Thiền.","detail":"Long khí từ hoàng cung phía dưới dâng lên và được Thạch Hạo dẫn vào kim liên đại đạo để đối kháng chân long, thần hoàng cùng thánh lực ánh trăng.","theLucLienQuan":[],"nguon":["@c0531"]},{"id":"tran-vuc-thien-thach","name":"Trận vực thiên thạch","cn":"","capDo":"khac","parentId":null,"blurb":"Khoảng hư không chứa nhiều thiên thạch và núi đá do trận pháp triệu hoán.","detail":"Nơi Thạch Hạo truy kích chủ thân Nguyệt Thiền qua trận pháp thiên thạch. Khu vực này cũng che giấu các đại pháp kỳ cấp Thần và chân thân Thạch Hạo trước cuộc phản kích.","theLucLienQuan":[],"nguon":["@c0531"]},{"id":"the-gioi-hop-bau","name":"Thế giới hộp báu","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian nội bộ của Hộp quý đồng thau.","detail":"Thạch Hạo đưa thứ thân Nguyệt Thiền vào không gian này để tránh dư lực của cuộc quyết chiến. Sau khi sát trận phát uy, chiếc hộp chứa thế giới này bị chủ thân Nguyệt Thiền thu lấy.","theLucLienQuan":[],"nguon":["@c0531"]},{"id":"chien-vuc-than-ma-dia-danh","name":"Chiến vực Thần ma","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian chiến trường diễn hóa sơn hà, nơi Bóng Lông và Con chim đỏ nhỏ giao chiến.","detail":"Chiến vực phong tỏa cuộc chiến giữa hai sinh linh đã bước đầu nhen nhóm Thần hỏa, ngăn sức phá hoại lan tới Đại hoang. Sơn hà bị phá hủy bên trong có thể phục hồi.","theLucLienQuan":[],"nguon":["@c0535"]},{"id":"khu-vuc-than-bi-cua-thuong-gioi","name":"Khu vực thần bí của thượng giới","cn":"","capDo":"vuc","parentId":"thuong-gioi","blurb":"Những vùng rộng lớn gần như chưa được thăm dò tại thượng giới.","detail":"Ngay cả các giáo chủ từng gây đại kiếp cũng chỉ thăm dò được một phần nhỏ, còn hơn chín mươi phần trăm khu vực chưa từng đặt chân tới. Liễu Thần suy đoán đích đến của mình có thể nằm ở nơi sâu nhất trong vùng này.","theLucLienQuan":[],"nguon":["@c0535"]},{"id":"duoc-do","name":"Dược đô","cn":"","capDo":"thanh","parentId":"hoa-quoc","blurb":"Khu vực thuộc cảnh nội Hỏa quốc, gần nơi sinh trưởng của linh căn đệ nhất thượng giới.","detail":"Một sơn cốc gần Dược đô trồng linh căn do sinh linh đáng sợ hóa thành. Nơi này từng bị nhiều bá chủ công kích trong đại kiếp.","theLucLienQuan":[],"nguon":["@c0536"]},{"id":"troi-xanh","name":"Trời xanh","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi được Liễu Thần gắn với con đường siêu thoát.","detail":"Liễu Thần chọn trời xanh làm nơi hẹn gặp lại Thạch Hạo trong tương lai sau khi bước vào con đường qua cánh cửa nguyên thủy.","theLucLienQuan":[],"nguon":["@c0536"]},{"id":"ba-ngan-gioi","name":"Ba ngàn giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Những chùm sáng hóa thành vô số thế giới xuất hiện quanh nhân thân áo trắng của Liễu Thần.","detail":"Ba ngàn giới đại diện cho Thần quốc, thế giới, lao tù và những con đường Liễu Thần từng trải qua. Bên trong có thần linh cùng vô tận chúng sinh quỳ lạy.","theLucLienQuan":["Tế Linh"],"nguon":["@c0536"]},{"id":"te-dan-to-tien-trong-hoang-cung-thach-quoc","name":"Tế đàn tổ tiên trong hoàng cung Thạch Quốc","cn":"","capDo":"khac","parentId":"thach-quoc-dia-danh-c0192","blurb":"Điểm tiếp nhận truyền tống nằm trong hoàng cung Thạch Quốc.","detail":"Thạch Hạo cùng Tần Hạo, Thứ thân Nguyệt Thiền và nhóm thiếu niên Thạch thôn xuất hiện tại đây sau khi dùng tế đàn mới rời Thạch thôn.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0537"]},{"id":"ngu-hoa-vien-hoang-toc-thach-quoc","name":"Ngự hoa viên hoàng tộc Thạch Quốc","cn":"","capDo":"khac","parentId":"thach-quoc-dia-danh-c0192","blurb":"Khu vườn trong hoàng cung Thạch Quốc.","detail":"Cảnh quan nơi đây khiến các thiếu niên vừa rời Thạch thôn kinh ngạc khi lần đầu đặt chân tới hoàng cung.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0537"]},{"id":"hoang-thien-vuong-phu-dia-danh","name":"Hoang Thiên vương phủ","cn":"","capDo":"khac","parentId":"thach-quoc-dia-danh-c0192","blurb":"Vương phủ tại Thạch Quốc, nơi Bì Hầu được đưa tới để trải nghiệm thế giới hồng trần.","detail":"Sau khi trở lại Thạch Quốc, Thạch Hạo đưa Bì Hầu tới Hoang Thiên vương phủ để được dẫn đi quan sát và trải nghiệm hồng trần.","theLucLienQuan":["Hoang Thiên vương phủ","Thạch Quốc"],"nguon":["@c0537"]},{"id":"minh-tho-dia-danh","name":"Minh thổ","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường cổ đại có âm khí cực thịnh, nơi linh hồn người chết tụ lại không tan.","detail":"Minh thổ là một chiến trường nổi danh từ thời cổ đại. Âm khí quá thịnh khiến linh hồn người chết hội tụ, một số khu vực còn được tương truyền đã hình thành vùng đất Luân hồi; trong chương này nơi đây được mở ra để triệu hoán anh linh vượt giới thăm dò Hoang vực.","theLucLienQuan":["Minh thổ"],"nguon":["@c0538"]},{"id":"sinh-tu-gioi","name":"Sinh tử giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một cảnh giới liên quan đến sức mạnh luân hồi, có thể được bóng người mơ hồ cầm Luân Hồi Bàn mở ra bằng một nắm tay.","detail":"Sinh tử giới được nhắc đến khi đánh giá thực lực của người nắm giữ Luân Hồi Bàn. Khả năng mở cảnh giới này gắn với uy hiếp đẩy chúng sinh hoặc bảo vật vào luân hồi.","theLucLienQuan":[],"nguon":["@c0540"]},{"id":"hon-don","name":"Hỗn độn","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian bên ngoài hạ giới, nơi Liễu Thần chuyển toàn bộ chiến trường để tránh làm hại người vô tội.","detail":"Liễu Thần mang theo sát trận thứ tư và các lực lượng tham chiến xuyên qua vết rách hư không để tiến vào hỗn độn. Các bá chủ thượng giới lập tức đuổi theo vì không muốn bỏ lỡ bí mật của cánh cửa nguyên thủy.","theLucLienQuan":[],"nguon":["@c0541"]},{"id":"dao-son-trong-canh-noi-thach-quoc","name":"Đạo sơn trong cảnh nội Thạch quốc","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Tòa đạo sơn gần Hoàng đô, nơi chủ thân Nguyệt Thiền và các hậu duệ thượng giới tụ hội.","detail":"Chủ thân Nguyệt Thiền, Ma nữ, Tuyên Minh, Bích Cổ, Thủy Nguyệt và những người khác cùng xuất hiện tại đây. Thạch Hạo rời cung tới đạo sơn để dự hội và dò hỏi tin tức về đại kiếp.","theLucLienQuan":["Bổ Thiên giáo","Thạch quốc"],"nguon":["@c0541"]},{"id":"hac-minh-son","name":"Hạc Minh sơn","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Dãy đồi núi thuộc mạch Đạo gia, có suối, rừng tùng, quán nhỏ bỏ hoang và nhiều di tích cổ. Đây là nơi diễn ra cuộc tụ hội của các thiên tài thượng giới và tám vực.","detail":"Thạch Hạo tới Hạc Minh sơn để xem những hình khắc cổ và tìm hiểu bí mật Bồ Ma thụ. Sâu trong vùng núi là nơi Bích Cổ cùng nhiều thiên tài tổ chức tụ hội, trao đổi về thượng giới và tranh nhau mời Thạch Hạo gia nhập các thế lực.","theLucLienQuan":["Học viện Trục Lộc","Học viện Sinh Mệnh","Xích hoàng cung","Bổ Thiên giáo","Tây Phương giáo"],"nguon":["@c0542"]},{"id":"ma-nhai-hac-minh-son","name":"Ma nhai Hạc Minh sơn","cn":"","capDo":"khac","parentId":"hac-minh-son","blurb":"Vách đá có các hình khắc cổ tại Hạc Minh sơn. Một hình khắc Bồ Ma thụ khiến Thạch Hạo chú ý tới lịch sử của hung thụ này.","detail":"Các hình khắc trên ma nhai ghi lại dấu vết lịch sử của Hạc Minh sơn và hình tượng Bồ Ma thụ. Từ đây, Thạch Hạo nhớ lại truyền thuyết về hung thụ từng khiến nhiều thần thánh thời thượng cổ bỏ mạng.","theLucLienQuan":[],"nguon":["@c0542"]},{"id":"vung-nui-rung-tung","name":"Vùng núi rừng tùng","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Vùng núi phủ rừng tùng, nơi nhiều thế lực thượng giới hội tụ để tranh đoạt thiên cốt của Thạch Hạo.","detail":"Thần phó Minh thổ và vị Thần Bất Lão sơn bay lên trời cao giao chiến để tránh phá hủy toàn bộ vùng núi. Sau đó Ma Quỳ viên cùng các cường giả khác tiếp tục xuất hiện tại đây, khiến cuộc tranh đoạt thiên cốt mở rộng.","theLucLienQuan":["Minh thổ","Bất Lão sơn","Ma Quỳ viên","Bổ Thiên giáo"],"nguon":["@c0544"]},{"id":"ma-quy-vien","name":"Ma quỳ viên","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Một phương Ma thổ đáng sợ ở thượng giới, đồng thời là địa bàn của thế lực Ma quỳ viên.","detail":"Nơi này được mô tả là chúa tể một phương của hệ Thực vật tại thượng giới. Các sinh linh Ma quỳ hạ giới có nguồn gốc từ đây.","theLucLienQuan":["Ma quỳ viên"],"nguon":["@c0545"]},{"id":"phong-than-dai","name":"Phong thần đài","cn":"","capDo":"khac","parentId":null,"blurb":"Địa danh được dùng làm hình ảnh so sánh địa vị áp đảo của sinh linh đã nhen nhóm Thần hỏa.","detail":"Phong thần đài được nhắc tới khi mô tả khoảng cách địa vị giữa cường giả đã nhen nhóm Thần hỏa và tu sĩ Tôn giả.","theLucLienQuan":[],"nguon":["@c0546"]},{"id":"bo-thien-giao-dia-danh","name":"Bổ Thiên giáo","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Một điểm giáng lâm của Sinh linh Bất diệt trong cuộc Phong thần.","detail":"Sinh linh Bất diệt tới Bổ Thiên giáo, bắt nhiều bóng người và một vị thần hóa sinh từ núi.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0546"]},{"id":"tay-phuong-giao-dia-danh","name":"Tây Phương giáo","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Một điểm Sinh linh Bất diệt ghé tới trong hành trình thanh trừng thần linh.","detail":"Sinh linh Bất diệt xuất hiện bên ngoài Tây Phương giáo và nuốt một luồng kim thân đang bị giam giữ.","theLucLienQuan":["Tây Phương giáo"],"nguon":["@c0546"]},{"id":"biet-vien-bo-thien-giao-ngoai-vuc","name":"Biệt viện Bổ Thiên giáo ngoài vực","cn":"","capDo":"khac","parentId":"vuc-ngoai","blurb":"Một cung điện cổ của Bổ Thiên giáo lơ lửng giữa quần thể thiên thạch ngoài vực.","detail":"Đây là nơi một cường giả thượng giới ẩn náu trước khi bị Sinh linh Bất diệt tìm tới, trói buộc và tiêu diệt trong cuộc săn thần.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0547"]},{"id":"phe-tich-bo-thien-cac","name":"Phế tích Bổ Thiên Các","cn":"","capDo":"khac","parentId":"tam-vuc","blurb":"Di chỉ đổ nát của Bổ Thiên Các sau biến cố diệt môn. Nơi đây lưu giữ ký ức tu hành và những mất mát của Thạch Hạo.","detail":"Thạch Hạo trở lại phế tích, tưởng niệm các đồng môn và trưởng lão đã hy sinh, dựng bia đá khắc tên môn phái rồi tuyên bố sẽ tái lập Bổ Thiên Các.","theLucLienQuan":["Bổ Thiên Các"],"nguon":["@c0548"]},{"id":"dam-lon-gan-bo-lac-tieu-thi","name":"Đầm lớn gần bộ lạc Tiêu thị","cn":"","capDo":"khac","parentId":"tam-vuc","blurb":"Một vùng đầm hồ rộng lớn cạnh nơi cư trú của bộ lạc Tiêu thị. Tiêu Thiên tu hành bên hồ tại khu vực này.","detail":"Thạch Hạo tìm đến vùng đầm lớn để gặp Tiêu Thiên. Bộ lạc Tiêu thị đông đảo sinh sống quanh hồ nước và có khu trung tâm quy mô tương đương một tiểu quốc.","theLucLienQuan":["Bộ lạc Tiêu thị"],"nguon":["@c0548"]},{"id":"co-dia-thac-bat-gia","name":"Cổ địa Thác Bạt gia","cn":"","capDo":"khac","parentId":null,"blurb":"Bảo địa và sơn môn của Thác Bạt gia, mục tiêu đầu tiên trong cuộc báo thù của Thạch Hạo.","detail":"Cổ địa có sơn môn được luyện từ hai tòa núi đá, long khí lượn quanh và đại trận hộ tộc bảo vệ. Thạch Hạo phá nát sơn môn cùng đại trận rồi tiến sâu vào trong, liên tiếp đánh chết các cường giả ngăn đường.","theLucLienQuan":["Thác Bạt gia"],"nguon":["@c0549"]},{"id":"tru-dia-thac-bat-toc","name":"Trụ địa Thác Bạt tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Trụ địa chính của Thác Bạt tộc, gồm quần thể núi đá được bố trí thành đại trận Tinh đấu.","detail":"Nơi đây bị Thạch Hạo dùng thần khí Thạch quốc công phá. Sau trận chiến, các trận đài và núi đá mất liên hệ với tinh tú, còn kiến trúc bị ngân diễm thiêu hủy.","theLucLienQuan":["Thác Bạt tộc"],"nguon":["@c0550"]},{"id":"bi-tho-thac-bat-toc","name":"Bí thổ Thác Bạt tộc","cn":"","capDo":"gioi-nho","parentId":"tru-dia-thac-bat-toc","blurb":"Đường lui dự phòng cất giữ một phần nội tình và cao thủ của Thác Bạt tộc.","detail":"Vị trí bí thổ bị nhóm Thạch Hạo điều tra ra. Toàn bộ cao thủ ẩn náu tại đây bị tiêu diệt, khiến Thác Bạt tộc mất căn cơ cuối cùng trong giới tu hành.","theLucLienQuan":["Thác Bạt tộc"],"nguon":["@c0550"]},{"id":"su-son","name":"Sư Sơn","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi rộng lớn, cao và khô cằn, là địa bàn của Cửu đầu sư tử nhất mạch.","detail":"Sư Sơn ít cây cỏ nhưng có nhiều linh dược lâu năm. Đây là quê nhà Kim Hoành và nơi Cửu Linh Vương đứng đầu nhất mạch Cửu đầu sư tử.","theLucLienQuan":["Cửu đầu sư tử nhất mạch"],"nguon":["@c0550"]},{"id":"dong-co-tai-su-son","name":"Động cổ tại Sư Sơn","cn":"","capDo":"khac","parentId":"su-son","blurb":"Động cổ tỏa ánh vàng, được sương mù và thần năng mạnh bao phủ.","detail":"Một cường giả cấp Tôn giả từ thượng giới đang ngủ bên trong động, khiến Thạch Hạo nhận ra Sư Sơn có khí tức Tôn giả thứ hai ngoài Cửu Linh Vương.","theLucLienQuan":["Cửu đầu sư tử nhất mạch"],"nguon":["@c0550"]},{"id":"dong-co-cua-cuu-linh-vuong","name":"Động cổ của Cửu Linh Vương","cn":"","capDo":"khac","parentId":"su-son","blurb":"Bảo địa bế quan của Cửu Linh Vương, có thạch nhũ lòng đất và Kim tinh khí.","detail":"Động cổ thích hợp cho bộ tộc Hoàng kim sư tử tu hành nhưng bị Tam hắc chiếm làm nơi uống rượu và gây sức ép với Cửu Linh Vương.","theLucLienQuan":["Cửu đầu sư tử nhất mạch","Tử Phủ sơn"],"nguon":["@c0551"]},{"id":"than-son-nam-van","name":"Thần sơn Nam Vẫn","cn":"","capDo":"vuc","parentId":"hoang-vuc","blurb":"Cấm địa của Hoang Vực, được xem là nơi cư trú của các thần linh thượng cổ.","detail":"Nam Vẫn nguy hiểm hơn nhiều Thái cổ Thần sơn, được bao phủ bởi biển sương mù và trận pháp khiến người tiến vào dễ mất phương hướng. Bên trong có ngọn núi đen cùng nghĩa địa chôn những thần linh sống sót từ thời thượng cổ.","theLucLienQuan":[],"nguon":["@c0551"]},{"id":"ngon-nui-den-trong-nam-van","name":"Ngọn núi đen trong Nam Vẫn","cn":"","capDo":"khac","parentId":"than-son-nam-van","blurb":"Ngọn núi hùng vĩ trong Thần sơn Nam Vẫn, được giọng nói già nua chỉ dẫn đoàn Thạch Hạo tìm tới.","detail":"Trên đỉnh núi có ông lão tóc trắng đốt giấy cúng và một khu nghĩa địa chôn các thần linh từng sống sót từ thời thượng cổ.","theLucLienQuan":[],"nguon":["@c0551"]},{"id":"nghia-dia-than-linh-nam-van","name":"Nghĩa địa thần linh Nam Vẫn","cn":"","capDo":"khac","parentId":"ngon-nui-den-trong-nam-van","blurb":"Khu nghĩa địa phủ đầy cỏ dại trên đỉnh ngọn núi đen tại Nam Vẫn.","detail":"Các ngôi mộ chôn những thần linh đã sống sót từ thời thượng cổ nhưng về sau lần lượt qua đời. Ông lão tóc trắng đốt giấy cúng tại đây và trực tiếp dẫn đoàn Thạch Hạo tới.","theLucLienQuan":[],"nguon":["@c0551"]},{"id":"nghi-son","name":"Nghi sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Cấm địa từng rất mạnh và có cường giả làm Tế linh cho Tiểu Tây Thiên.","detail":"Nghi sơn hiện khô cằn, cây cỏ thưa thớt vì từng trải qua đại chiến trong đại kiếp. Toàn bộ Tôn giả và cường giả nhen nhóm Thần hỏa tại đây đều đã bị trấn áp.","theLucLienQuan":["Nghi sơn","Tiểu Tây Thiên"],"nguon":["@c0552"]},{"id":"man-hoang-dai-dia-trong-tay-lang","name":"Man hoang đại địa trong Tây Lăng","cn":"","capDo":"gioi-nho","parentId":"tay-lang","blurb":"Không gian man hoang xuất hiện sau khi đoàn người tiến hơn mười dặm vào Tây Lăng.","detail":"Nơi này tái hiện cảnh tượng Thái Cổ với Kim Sí Đại Bằng, Tỳ Hưu, Chân Hống, Chu Yếm, Viêm Mãng và nhiều sinh linh đáng sợ. Các sinh linh có thể trực tiếp gây thương tích, cho thấy cảnh tượng không đơn thuần là ảo giác.","theLucLienQuan":["Thú sơn Tây Lăng"],"nguon":["@c0552"]},{"id":"tay-lang-gioi","name":"Tây Lăng Giới","cn":"","capDo":"gioi-nho","parentId":"tay-lang","blurb":"Thế giới nửa hư nửa thật tự diễn hóa bên trong nghĩa địa Tây Lăng.","detail":"Ý chí còn sót lại của vô số Thần Vương, Thiên Thần, hung thú và chim thần Thái Cổ đan xen thành sức mạnh tinh thần, từ đó xây dựng nên Tây Lăng Giới. Nơi đây có địa vực hữu hạn, âm khí nặng và đủ cô đọng để một phần thân thể của các anh linh hóa thành thực chất; trên đường thăm dò, nhóm Thạch Hạo gặp bia đá khắc tên thế giới này cùng nhiều anh linh cực mạnh.","theLucLienQuan":["Thú sơn"],"nguon":["@c0553","@c0579"]},{"id":"thiem-dien-thu","name":"Thiểm Điện thụ","cn":"","capDo":"khac","parentId":"tay-lang-gioi","blurb":"Cây kỳ dược mọc trong Tây Lăng Giới, kết Thiểm Điện quả và là nơi cư trú của Thiểm Điện trùng.","detail":"Thiểm Điện thụ cao vài trượng, mọc giữa vùng đất trọc, có cành lá trắng bạc và những tia chớp lượn lờ. Hương thơm từ quả dẫn nhóm Thạch Hạo tới đây; việc Tam hắc hái bốn quả lập tức kinh động đàn Thiểm Điện trùng trú trên cây.","theLucLienQuan":[],"nguon":["@c0553"]},{"id":"loi-ra-tay-lang-gioi","name":"Lối ra Tây Lăng giới","cn":"","capDo":"khac","parentId":"tay-lang-gioi","blurb":"Khu vực nối Tây Lăng giới với bên ngoài, nơi nhóm Thạch Hạo bị ba thủ lĩnh Thú sơn tập kích.","detail":"Thạch Hạo và Huyền Quy chống lại tử khí tại đây. Tôn giả Bạch Hổ cùng Sư tử già và Voi lớn cũng chọn nơi này để bao vây, tập kích cả nhóm.","theLucLienQuan":["Thú sơn Tây Lăng"],"nguon":["@c0554"]},{"id":"te-dan-xuong-cot","name":"Tế đàn xương cốt","cn":"","capDo":"khac","parentId":"tay-lang-gioi","blurb":"Tế đàn nằm sâu trong Tây Lăng giới, xung quanh chất đầy xương cốt như một nơi hiến tế.","detail":"Trên tế đàn có nhiều khối cốt đặc biệt, trong đó một khối nhỏ trắng bóng như ngọc khiến Nguyên Thủy Chân Cốt trong tay Thạch Hạo phát sáng cảm ứng.","theLucLienQuan":[],"nguon":["@c0554"]},{"id":"te-dan-da-den","name":"Tế đàn đá đen","cn":"","capDo":"khac","parentId":"tay-lang-gioi","blurb":"Tế đàn cổ bằng đá đen nằm giữa Tây Lăng giới, chất đầy xương hung thú và chim thần Thái Cổ.","detail":"Tại trung tâm tế đàn đặt mảnh Nguyên Thủy Chân Cốt cuối cùng cùng xương tay vàng, xương sọ thủy tinh và tròng mắt dính máu. Sau khi chân cốt bị lấy, nơi này phát ra gợn sóng đen nghiền nát cảnh vật và kích động nhiều sinh linh cổ truy sát Thạch Hạo.","theLucLienQuan":[],"nguon":["@c0555"]},{"id":"te-dan-bat-lao-son-huyen-vuc","name":"Tế đàn Bất Lão sơn ở Huyền vực","cn":"","capDo":"khac","parentId":"huyen-vuc","blurb":"Tế đàn tại Bất Lão sơn ở Huyền vực, nơi Tần Hạo tiếp nhận hình chiếu của khối cốt thần bí.","detail":"Tế đàn liên hệ với thượng giới để hình chiếu khối cốt giao hòa với Tần Hạo. Khu vực này không còn sinh linh đã nhen nhóm Thần hỏa canh giữ.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0557"]},{"id":"khu-vuc-khong-nguoi-than-bi","name":"Khu vực không người thần bí","cn":"","capDo":"vuc","parentId":"thuong-gioi","blurb":"Vùng hiểm địa rộng lớn chiếm phần lớn thượng giới, ngay cả các giáo chủ cũng khó xâm nhập.","detail":"Nơi đây có nhiều báu vật và cổ dược thần thánh nhưng cực kỳ nguy hiểm. Bất Lão Thiên Tôn từng lấy được khối cốt thần bí từ một tế đàn cổ tại đây, còn Sinh linh Bất Diệt trốn vào vùng này sau khi bị các bá chủ truy ép.","theLucLienQuan":[],"nguon":["@c0557"]},{"id":"duoc-vien-hoang-cung-thach-quoc","name":"Dược viên hoàng cung Thạch quốc","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Dược viên trong hoàng cung được bổ sung linh dược do các chư hầu dâng lên.","detail":"Thạch Hạo cùng Thanh Phong ở đây chuẩn bị dược liệu và luyện thành hai lò gồm sáu viên Tiểu Niết Bàn đan.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0558"]},{"id":"so-thuy-dia","name":"Sơ Thủy địa","cn":"","capDo":"khac","parentId":"hu-than-gioi","blurb":"Khu vực thấp nhất và điểm bắt đầu của Hư Thần giới.","detail":"Điểu gia và Tinh Bích đại gia bày quán bán sổ tay cùng cốt thư giả tại đây. Thạch Hạo tìm gặp hai lão ở Sơ Thủy địa rồi bắt đầu hành trình liên tiếp phá kỷ lục.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0559"]},{"id":"thien-lo","name":"Thiên lộ","cn":"","capDo":"khac","parentId":"hu-than-gioi","blurb":"Con đường đá cổ xưa lơ lửng trong hư không và uốn lượn lên trời.","detail":"Thiên lộ mang áp lực tăng dần, khiến tu sĩ bình thường khó nhấc bước và buộc Thạch Hạo phải đi suốt ba ngày ba đêm mới tới điểm cuối. Người bước sai có thể rơi xuống vực sâu chứa sát khí và bị cắt nát, còn người vượt qua toàn bộ đối thủ mới có cơ hội nhận hai khối đồng thau cuối.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0560"]},{"id":"dai-dong-thau-cuoi-thien-lo","name":"Đài đồng thau cuối thiên lộ","cn":"","capDo":"khac","parentId":"thien-lo","blurb":"Đài cao rộng lớn lơ lửng trong hư không tại điểm cuối thiên lộ.","detail":"Đài đồng thau vừa giống tế đàn cổ vừa giống võ đài, trên bề mặt có những hình sinh linh chạm khắc phủ gỉ đồng xanh. Một tầng sức mạnh vô hình bảo vệ lối vào, buộc Thạch Hạo phải đánh tan mới có thể bước lên.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0560"]},{"id":"hai-canh-cua-dong-thau","name":"Hai cánh cửa đồng thau","cn":"","capDo":"khac","parentId":"hu-than-gioi","blurb":"Hai cánh cửa khổng lồ như núi phong kín lối vào khu vực thiên lộ.","detail":"Tinh Bích đại gia dùng phù quang mở hai cánh cửa đồng thau. Khi cửa mở, khí hỗn độn tràn ra và con đường đá uốn lượn dẫn lên trời mới hiện rõ.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0560"]},{"id":"ngon-nui-quan-chien","name":"Ngọn núi quan chiến","cn":"","capDo":"khac","parentId":"hu-than-gioi","blurb":"Ngọn núi đen cao tới mây xanh, nằm song song với thiên lộ.","detail":"Tinh Bích đại gia đưa những người quan sát lên ngọn núi này để theo dõi hành trình của Thạch Hạo. Núi nằm không quá xa thiên lộ nhưng người đứng trên đó không thể tiếp xúc trực tiếp với con đường.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0560"]},{"id":"linh-vuc-cam-khong","name":"Lĩnh vực cấm không","cn":"","capDo":"vuc","parentId":"hu-than-gioi","blurb":"Khu vực cấm phi hành bao quanh thiên lộ và ngọn núi quan chiến.","detail":"Quy tắc cấm không khiến người rơi khỏi thiên lộ không thể tự bay trở lại. Bên dưới con đường là vực sâu có sát khí đủ sức cắt nát những người thất bại.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0560"]},{"id":"dai-dong-tuc","name":"Đài Đồng Tức","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm Phượng Vũ tới để kính viếng và tưởng nhớ phong thái của tiền nhân.","detail":"Phượng Vũ cho biết mục đích nàng tới đài Đồng Tức là kính viếng tiền nhân. Chương này chưa xác nhận đài Đồng Tức và đàn Đồng Tước là cùng một địa điểm.","theLucLienQuan":["Tiên viện"],"nguon":["@c0561"]},{"id":"dan-dong-tuoc","name":"Đàn Đồng Tước","cn":"","capDo":"khac","parentId":null,"blurb":"Tế đàn đồng thau kiên cố, có khả năng áp chế tu vi để đưa những người giao chiến về cùng cảnh giới.","detail":"Thạch Hạo và Phượng Vũ giao chiến trên đàn Đồng Tước. Nơi đây nối với một con đường có hình chiếu về thế giới hùng vĩ phía trên; Phượng Vũ sau đó rời tế đàn theo một lối nhỏ.","theLucLienQuan":[],"nguon":["@c0561"]},{"id":"con-duong-huong-len-tren","name":"Con đường hướng lên trên","cn":"","capDo":"khac","parentId":"dan-dong-tuoc","blurb":"Con đường đối diện Thạch Hạo, thấp thoáng hình chiếu của một thế giới hùng vĩ.","detail":"Qua hình chiếu trên con đường có thể nhìn thấy tiên vụ, cổ mộc, núi cao cùng bóng dáng chim thần và cự thú. Đích đến cụ thể của con đường chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c0561"]},{"id":"hai-canh-cua-vang","name":"Hai cánh cửa vàng","cn":"","capDo":"khac","parentId":null,"blurb":"Hai cánh cửa cao hơn núi nằm ngoài đàn Đồng Tước và đang mở hé.","detail":"Cuộc truy đuổi giữa Thạch Hạo và Phượng Vũ dẫn tới hai cánh cửa vàng. Phía trước cửa có một người đá đã nhen nhóm Thần hỏa ngồi xếp bằng trấn thủ.","theLucLienQuan":[],"nguon":["@c0561"]},{"id":"cua-hoang-kim","name":"Cửa Hoàng kim","cn":"","capDo":"khac","parentId":"hu-than-gioi","blurb":"Cánh cửa vàng khổng lồ trên thiên lộ, dẫn tới khu vực mô phỏng núi non, thác nước và tiên khí của thế giới hiện thực.","detail":"Người đá mang thần hỏa ngồi gần cửa và có thể thiêu hủy thần lực tới gần. Theo Điểu gia, Thạch Hạo phải vượt qua cánh cửa này mới có thể chiếm được Sách quý đồng thau.","theLucLienQuan":["Hư Thần giới"],"nguon":["@c0562"]},{"id":"hoc-vien-thien-tien","name":"Học viện Thiên Tiên","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Phượng Vũ tu hành và là địa điểm bản thể nàng tỉnh lại sau khi Binh giải khỏi Hư Thần giới.","detail":"Tại đây, Phượng Vũ tỉnh lại trong trang phục hoàng kim với nguyên khí dường như bị tổn thương. Nàng vẫn tức giận vì cuộc đối đầu với Thạch Hạo và bắt đầu quan tâm liệu sau này nó có tới Tiên viện hay không.","theLucLienQuan":["Tiên viện"],"nguon":["@c0562"]},{"id":"linh-gioi","name":"Linh giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới tinh thần nằm phía sau cửa Hoàng kim, chỉ cho phép linh thức tiến vào.","detail":"Linh giới do chư thần thượng giới từ thời Thái Cổ dùng tinh thần xây dựng. Người từ Linh giới có thể mở cửa Hoàng kim từ phía trong để đi tới đàn Đồng Tước.","theLucLienQuan":[],"nguon":["@c0563"]},{"id":"thien-tien-chau","name":"Thiên Tiên châu","cn":"","capDo":"chau","parentId":"thuong-gioi","blurb":"Một châu thuộc thượng giới, nơi Phượng Vũ nổi danh trong thế hệ trẻ.","detail":"Tin tức sai lệch về đại hung Hạo Thiên từ Linh giới truyền tới Thiên Tiên châu, khiến nhiều tu sĩ và cả những thiên kiêu được gọi là sơ đại chú ý.","theLucLienQuan":["Hỏa Vân Động","Học viện Thiên Tiên"],"nguon":["@c0563"]},{"id":"kim-cuong-tri","name":"Kim Cương trì","cn":"","capDo":"khac","parentId":"tay-phuong-giao-dia-danh","blurb":"Một nơi tôi luyện thân thể thuộc Tây Phương giáo.","detail":"Chân Lôn từng ngâm mình trong Kim Cương trì suốt bốn mươi chín ngày, qua đó có được thân thể được gọi là bất hoại.","theLucLienQuan":["Tây Phương giáo"],"nguon":["@c0564"]},{"id":"muoi-van-thanh-son","name":"Mười vạn Thánh sơn","cn":"","capDo":"chau","parentId":null,"blurb":"Một châu nguyên thủy có mười vạn ngọn núi, nằm rất xa Thiên Tiên châu.","detail":"Đằng Nhất từng quét ngang các cường giả tại khu vực này. Hắn tới đàn Đồng Tước với ý định hàng phục Thạch Hạo và bắt đối phương về bảo vệ sơn môn của mình.","theLucLienQuan":["Tộc Hỏa Kim"],"nguon":["@c0565"]},{"id":"phu-hon-thien-hau","name":"Phủ Hỗn Thiên hầu","cn":"","capDo":"khac","parentId":"bien-gioi-phia-tay-thach-quoc","blurb":"Phủ Vương hầu của Thạch Hằng tại thành trì ở biên giới phía Tây Thạch quốc. Đây là nơi âm mưu dụ Thạch Hạo tới biên giới bị công khai.","detail":"Tại phủ, thái độ lạnh lùng của Thạch Hằng khiến Thạch Hạo nhận ra tin báo về Thôn Thiên tước là một cái bẫy. Thạch Hằng thừa nhận Thần thượng giới muốn Nhân Hoàng chết và tuyên bố sẽ thay đối phương cai trị Thạch quốc.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0568"]},{"id":"ma-quy-vien-dia-danh","name":"Ma Quỳ viên","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Địa bàn của đạo thống Ma Quỳ viên tại thượng giới.","detail":"Bá chủ của Ma Quỳ viên cùng Minh chủ và chủ nhân Thiên quốc mở khe hở hư không để đưa sát thủ xuống hạ giới truy sát Thạch Hạo.","theLucLienQuan":["Ma Quỳ viên"],"nguon":["@c0570"]},{"id":"bao-kho-thach-quoc","name":"Bảo khố Thạch quốc","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Bảo khố cất giữ pháp khí và giáp trụ Chân Thần của Thạch quốc.","detail":"Thạch Hạo lấy giáp trụ cùng binh khí thần thánh tại đây rồi giao cho Tiểu Hồng và Bóng Lông sử dụng trong trận chiến với tượng thần mạ vàng.","theLucLienQuan":["Thạch quốc","Nhân Hoàng Thạch quốc"],"nguon":["@c0570"]},{"id":"bien-gioi-phia-tay","name":"Biên giới phía Tây","cn":"","capDo":"vuc","parentId":"thach-quoc","blurb":"Khu vực biên giới của Thạch quốc nơi diễn ra chiến dịch bình loạn do Thạch Hạo chỉ huy.","detail":"Tại đây, Thạch Hạo cùng Bóng Lông và Tiểu Hồng đối đầu phe Thạch Hằng, ông lão áo xám và cường giả Thiên quốc. Chiến dịch kết thúc khi Huyết Ma thước bị hủy, ông lão áo xám bị giết và Thạch Hằng tự sát sau khi bị phế tu vi.","theLucLienQuan":["Thạch quốc","Thiên quốc"],"nguon":["@c0571"]},{"id":"tam-sinh-son","name":"Tam Sinh Sơn","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Đạo sơn cách hoàng đô Thạch quốc hơn hai vạn dặm, có núi non liên miên và linh khí mịt mờ. Thạch Hạo dựng nhà lá trên một đỉnh núi nhỏ để công khai bế quan.","detail":"Thạch Hạo chọn Tam Sinh Sơn làm nơi thu hút các cường giả thượng giới có ý định trả thù, qua đó tránh để Thạch quốc và thân hữu bị liên lụy.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0572"]},{"id":"dien-phu-co-thuong-gioi","name":"Điện phủ cổ thượng giới","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Điện phủ cổ tràn ngập khí hỗn độn, có nhiều bồ đoàn dành cho các bóng người bí ẩn. Đây là nơi các đại năng bàn bạc kế hoạch chiến thiên ý.","detail":"Những người tụ họp tại điện phủ thống nhất đánh đổi để đưa cường giả đã nhen nhóm Thần hỏa xuống hạ giới, đồng thời thảo luận phương tiện phá giới và mục tiêu cần loại bỏ.","theLucLienQuan":["Minh thổ","Thiên quốc"],"nguon":["@c0572"]},{"id":"hong-vuc","name":"Hồng vực","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực hạ giới nơi tế đàn huyết tế được dựng và nhiều vụ thu bắt sinh linh đồng loạt diễn ra. Biến cố tại đây làm cả hạ giới lẫn thượng giới rung chuyển.","detail":"Các địa điểm bị tập kích trong Hồng vực gồm một Cổ quốc vô danh, quốc thổ Mộc tộc và những vùng khác. Sinh linh bị thu bằng ống tay áo, hồ lô máu và túi càn khôn để phục vụ nghi thức phá giới.","theLucLienQuan":["Mộc tộc","Các đại giáo bất hủ hạ giới"],"nguon":["@c0572"]},{"id":"dam-lay-hong-vuc","name":"Đầm lầy Hồng vực","cn":"","capDo":"khac","parentId":"hong-vuc","blurb":"Vùng đầm lầy phủ sương mù dày đặc, nơi tế đàn đen khắc phù văn thần ma được dựng. Đây là điểm tập kết bí mật của những người thuộc nhiều đạo thống.","detail":"Tế đàn tại đầm lầy tạo áp lực lên linh hồn và được chuẩn bị cho hoạt động huyết tế quy mô lớn.","theLucLienQuan":[],"nguon":["@c0572"]},{"id":"co-quoc-vo-danh-tai-hong-vuc","name":"Cổ quốc vô danh tại Hồng vực","cn":"","capDo":"quoc-gia","parentId":"hong-vuc","blurb":"Một quốc gia không được nêu tên tại Hồng vực, bị bóng người bí ẩn phất tay áo cuốn đi vô số sinh linh. Sau cuộc tập kích, khu vực nhanh chóng trở nên vắng lặng.","detail":"Cổ quốc là một trong nhiều địa bàn bị quét sinh linh để cung cấp cho nghi thức huyết tế phá giới.","theLucLienQuan":[],"nguon":["@c0572"]},{"id":"quoc-tho-moc-toc","name":"Quốc thổ Mộc tộc","cn":"","capDo":"quoc-gia","parentId":"hong-vuc","blurb":"Vùng đất phồn hoa của Mộc tộc tại Hồng vực. Một bóng người đứng trên trời cao dùng hồ lô máu thu bắt sinh linh từ mười phương.","detail":"Quốc thổ Mộc tộc không thuộc Nhân tộc và là một trong những khu vực chịu nạn trong đợt thu sinh linh phục vụ huyết tế.","theLucLienQuan":["Mộc tộc"],"nguon":["@c0572"]},{"id":"co-dien-than-bi-o-thuong-gioi","name":"Cổ điện thần bí ở thượng giới","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Nơi các giáo chủ thượng giới hội họp và hợp lực mở thông đạo xuống hạ giới.","detail":"Cổ điện được bảo vệ bằng đại trận tuyệt thế nhưng vẫn bị thiên đao và tia chớp hỗn độn làm tổn hại trong lúc các giáo chủ chống lại thiên ý.","theLucLienQuan":["Minh thổ"],"nguon":["@c0573"]},{"id":"tran-nho-gan-tam-sinh-son","name":"Trấn nhỏ gần Tam Sinh sơn","cn":"","capDo":"thanh","parentId":null,"blurb":"Một trấn nhỏ gần nơi Thạch Hạo tạm cư tại Tam Sinh sơn. Nó tới đây dẫn trẻ nghèo đi mua thức ăn để tìm lại cảm giác tuổi thơ ở Thạch thôn.","detail":"Vì không dám trở về Thạch thôn và sợ dẫn tai họa tới quê nhà, Thạch Hạo tới trấn nhỏ này cùng cha mẹ. Nó dẫn một đám trẻ nghèo đi mua thức ăn, khiến Thạch Tử Lăng và Tần Di Ninh nhận ra nỗi nhớ quê sâu kín của con.","theLucLienQuan":[],"nguon":["@c0575"]},{"id":"vung-nui-co-sat-tran","name":"Vùng núi có sát trận","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng núi nơi Nguyệt Thiền tiên tử từng phục kích Thạch Hạo, về sau có sát trận được Đả Thần Thạch cải tạo.","detail":"Thạch Hạo dẫn ba kẻ truy sát tới đây và mở toàn bộ sát trận, khiến quần sơn rung động cùng sát quang sôi trào. Ba cường giả đã nhen Thần hỏa vẫn bình an thoát khỏi trận pháp.","theLucLienQuan":[],"nguon":["@c0577"]},{"id":"tu-dia-chua-ro-ten","name":"Tử địa chưa rõ tên","cn":"","capDo":"khac","parentId":null,"blurb":"Một nơi cực kỳ nguy hiểm mà Thạch Hạo từng chỉ nhờ may mắn mới sống sót rời khỏi.","detail":"Khi mọi cách chạy trốn đều thất bại, Thạch Hạo quyết định dẫn ba cường giả truy sát tới nơi này, chấp nhận cùng chết để kéo họ vào tuyệt cảnh.","theLucLienQuan":[],"nguon":["@c0577"]},{"id":"toa-thanh-lon-phia-bac","name":"Tòa thành lớn phía Bắc","cn":"","capDo":"thanh","parentId":"hoang-vuc","blurb":"Tòa thành ở phía Bắc Hoang vực có tế đàn truyền tống được Thạch Hạo sử dụng trong lúc đào thoát.","detail":"Sau khi bị ba cường giả Thần hỏa truy kích và đánh trọng thương, Thạch Hạo tìm tới tế đàn trong thành, mở một thông đạo màu vàng rồi truyền tống rời đi.","theLucLienQuan":[],"nguon":["@c0578"]},{"id":"vung-nui-go-mo","name":"Vùng núi gò mộ","cn":"","capDo":"khac","parentId":"tay-lang","blurb":"Khu vực gồm nhiều ngọn núi tròn nối tiếp nhau, có hình dáng như những ngôi mộ lớn.","detail":"Vùng núi là lối dẫn sâu vào Tây Lăng giới, nơi Thạch Hạo chủ động đưa ba cường giả Thần hỏa đang truy sát mình tiến vào.","theLucLienQuan":[],"nguon":["@c0578"]},{"id":"day-nui-chien-truong","name":"Dãy núi chiến trường","cn":"","capDo":"vuc","parentId":null,"blurb":"Chiến trường giữa Bóng Lông, Tiểu Hồng và cường giả Tây Phương giáo.","detail":"Trận chiến phá hủy khu vực, làm núi non sụp đổ và mặt đất hóa thành dung nham. Những mảnh thân thể, lông cánh và vũ khí gãy tại đây khiến Thạch Hạo ngộ nhận hai người bạn đã chết.","theLucLienQuan":["Thạch thôn","Tây Phương giáo"],"nguon":["@c0580"]},{"id":"di-tich-bo-thien-cac","name":"Di tích Bổ Thiên các","cn":"","aliases":["Phế tích Bổ Thiên các","Di chỉ Bổ Thiên các"],"capDo":"khac","parentId":null,"blurb":"Phế tích của Bổ Thiên các, nơi các công trình tái thiết bị một Thần hạ giới phá hủy.","detail":"Vị Thần xuất hiện tại đây phá hủy mọi thứ đang được xây dựng lại rồi dò xét khu vực như muốn mở Thánh viện thượng cổ.","theLucLienQuan":["Bổ Thiên các"],"nguon":["@c0580"]},{"id":"thanh-vien-thuong-co","name":"Thánh viện thượng cổ","cn":"","capDo":"khac","parentId":"di-tich-bo-thien-cac","blurb":"Một di tích cổ ẩn trong hư không tại khu vực Bổ Thiên các.","detail":"Vị Thần tại phế tích Bổ Thiên các dành nhiều canh giờ cảm ứng và tìm kiếm Thánh viện thượng cổ. Mục đích cụ thể của hắn tại di tích này chưa được hé lộ.","theLucLienQuan":["Bổ Thiên các"],"nguon":["@c0581"]},{"id":"day-nui-ngoai-bo-thien-cac","name":"Dãy núi ngoài Bổ Thiên các","cn":"","capDo":"vuc","parentId":"huyen-vuc","blurb":"Chiến trường nơi Thạch Hạo đánh bại và giết cường giả Ma Quỳ viên.","detail":"Vụ tự bạo của cường giả Ma Quỳ viên xóa sạch nhiều ngọn núi và để lại tàn tích rộng lớn. Vợ chồng Thạch Tử Lăng tới đây sau trận chiến và nhận ra Thạch Hạo đã giết một vị Thần.","theLucLienQuan":["Bổ Thiên các","Ma Quỳ viên"],"nguon":["@c0584"]},{"id":"dat-cu-thach-thon","name":"Đất cũ Thạch thôn","cn":"","capDo":"khac","parentId":"thach-thon","blurb":"Nơi cư trú trước kia của người Thạch thôn, từng nằm trong vùng bị tàn sát rộng năm vạn dặm.","detail":"Cỏ dại và thú dữ đã dần trở lại khu vực này sau thời gian dài hoang vắng. Dưới đáy một hố sâu tại đây có thần hài tử kim dài trăm trượng cùng hơn mười viên Thần tinh.","theLucLienQuan":["Thạch thôn"],"nguon":["@c0585"]},{"id":"thi-tran-ngoai-thach-do","name":"Thị trấn ngoài Thạch đô","cn":"","capDo":"thanh","parentId":"thach-quoc","blurb":"Một thị trấn nằm cách nơi Thạch Hạo và Hoàng Vũ đối đầu hơn mấy chục dặm.","detail":"Hoàng Vũ tạo vòng xoáy vàng hút cư dân từ thị trấn này tới chiến trường rồi nuốt sống mấy trăm người để uy hiếp Thạch Hạo.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0586"]},{"id":"vung-dat-hoang-cach-thach-do","name":"Vùng đất hoang cách Thạch đô mấy ngàn dặm","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Vùng núi hùng vĩ và hoang vắng nằm cách Thạch đô mấy ngàn dặm.","detail":"Thạch Hạo chủ động chọn nơi không có dân cư này làm chiến trường với Hoàng Vũ nhằm tránh để sức mạnh giao chiến lan tới người vô tội.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0586"]},{"id":"dai-hoang","name":"Đại hoang","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực Thạch Hạo dừng chạy trốn và quyết định tử chiến với Hoàng Vũ.","detail":"Trong Đại hoang, Thạch Hạo bí mật bố trí phù cốt màu tím trong hư không, dụ Hoàng Vũ tiến vào phạm vi rồi kích nổ để tìm cơ hội phản kích.","theLucLienQuan":[],"nguon":["@c0587"]},{"id":"thu-phu-thach-quoc","name":"Thủ phủ Thạch quốc","cn":"","capDo":"thanh","parentId":"thach-quoc","blurb":"Trung tâm của Thạch quốc, nơi Hoàng Vũ dùng làm mục tiêu uy hiếp Thạch Hạo.","detail":"Hoàng Vũ tuyên bố sẽ quay về thủ phủ và nuốt sạch trăm vạn người nếu Thạch Hạo tiếp tục chạy trốn, qua đó buộc đối phương phải tử chiến.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0587"]},{"id":"tieu-the-gioi-trong-tam-da-thu","name":"Tiểu thế giới trong tấm da thú","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian bí ẩn nằm trong quyển da thú gắn với nửa bộ Kiếm ý của Thạch Hạo.","detail":"Thạch Hạo từng nhiều lần thử mở tiểu thế giới này nhưng chưa thành công và mới chỉ nhìn thấy hai chữ “Lục đạo”. Hoàng Vũ nhận ra mối liên hệ giữa nó với Kiếm ý mà Thạch Hạo thi triển.","theLucLienQuan":[],"nguon":["@c0587"]},{"id":"dien-vo-truong-trong-buc-tuong-than-ma","name":"Diễn võ trường trong bức tường Thần ma","cn":"","capDo":"khac","parentId":"cung-dien-duoi-long-dat","blurb":"Sân quyết chiến ẩn trong bức tường Thần ma tại cung điện dưới lòng đất của tổ địa Hỏa quốc.","detail":"Diễn võ trường có khả năng áp chế cảnh giới và triệu xuất sinh linh tham chiến. Thạch Hạo dụ linh thân Hoàng Vũ vào đây, giao chiến cùng một con Chu Yếm rồi dùng kiếm gãy xuyên thủng mi tâm linh thân.","theLucLienQuan":["Hỏa quốc","Hỏa tộc"],"nguon":["@c0589"]},{"id":"vung-nui-noi-thach-hao-quyet-chien","name":"Vùng núi nơi Thạch Hạo quyết chiến","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Vùng núi diễn ra trận quyết chiến giữa Thạch Hạo và Hoàng Vũ.","detail":"Tại đây, Thạch Hạo tự hủy Chí Tôn cốt để tiêu diệt Hoàng Vũ rồi được cành liễu của Liễu Thần tạm ghép lại thân thể giữa núi rừng.","theLucLienQuan":["Tiên điện"],"nguon":["@c0591"]},{"id":"hac-thach-thanh","name":"Hắc Thạch thành","cn":"","capDo":"thanh","parentId":"hoang-vuc","blurb":"Một thành trì quy mô lớn được xây bằng nham thạch đen.","detail":"Thạch Hạo dừng tại Hắc Thạch thành để sửa tế đàn truyền tống bị hỏng. Trước khi nó kịp rời đi, Thạch Tử Lăng, Tần Di Ninh và Tần Hạo đã tìm tới.","theLucLienQuan":[],"nguon":["@c0593"]},{"id":"noi-o-cua-tan-toc","name":"Nơi ở của Tần tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo được chữa trị sau khi trúng cốt văn nguyền rủa. Đây cũng là địa điểm Tần Lan lẻn vào ám sát cậu trong đêm.","detail":"Thạch Hạo nằm dưỡng thương tại nơi ở của Tần tộc trong lúc cha mẹ cậu cân nhắc phương án chuyển Tiên cốt. Tần Lan lợi dụng ban đêm để tiếp cận phòng bệnh và tìm cách đánh vào mi tâm cậu, dẫn tới cuộc phản kích và xung đột với những người Tần tộc kéo tới sau đó.","theLucLienQuan":["Tần tộc"],"nguon":["@c0594"]},{"id":"son-mon-bat-lao-son","name":"Sơn môn Bất Lão sơn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Cửa vào Bất Lão sơn, nơi đoàn các Vương và vương hầu Thạch quốc được đón vào khi mang bảo dược tới cứu Thạch Hạo.","detail":"Tần tộc mở sơn môn để tiếp đón Chiến vương, Minh vương, Bằng Cửu cùng đoàn cường giả Thạch quốc mang theo đan dược và thánh dược.","theLucLienQuan":["Bất Lão sơn","Tần tộc","Thạch quốc"],"nguon":["@c0595"]},{"id":"toa-thanh-gan-bat-lao-son","name":"Tòa thành gần Bất Lão sơn","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành gần Bất Lão sơn nơi đoàn người dừng lại sau khi đưa Thạch Hạo rời khỏi sơn môn.","detail":"Tế đàn tại đây được mở để tạo thông đạo đưa Thạch Hạo cùng người Thạch thôn và Chiến vương trở về Thạch quốc.","theLucLienQuan":["Thạch quốc","Thạch thôn"],"nguon":["@c0597"]},{"id":"than-lo-coc","name":"Thần Lô cốc","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc có hình dáng như một lò thần, gắn với truyền thuyết huyết tế để cầu Cửu chuyển thần đan.","detail":"Người thường tiến vào Thần Lô cốc dễ gặp chuyện kỳ dị và mất mạng. Tương truyền người thành tâm huyết tế tại đây có thể cầu được Cửu chuyển thần đan, nhưng những trường hợp từng thử đều không thu được gì nên truyền thuyết chưa được chứng thực.","theLucLienQuan":[],"nguon":["@c0598"]},{"id":"ngon-nui-thap-ngoai-thach-thon","name":"Ngọn núi thấp ngoài Thạch thôn","cn":"","capDo":"khac","parentId":"dai-hoang","blurb":"Ngọn núi thấp cách Thạch thôn mười dặm, được Thạch Hạo chọn làm nơi an táng trong những giờ phút cuối.","detail":"Nơi này có cổ tùng, dòng suối và không gian yên tĩnh. Tuy không phải linh thổ, từ đây vẫn có thể nhìn thấy Thạch thôn ở phía xa.","theLucLienQuan":["Thạch thôn"],"nguon":["@c0599"]},{"id":"do-thanh-thach-quoc","name":"Đô thành Thạch quốc","cn":"","capDo":"thanh","parentId":"thach-quoc","blurb":"Kinh đô Thạch quốc, nơi diễn ra cuộc tiễn đưa Thạch Hạo về quê.","detail":"Khi Thạch Hạo rời đi, đông đảo cường giả, giáo chủ và dân chúng đồng thanh tiễn Thạch Hoàng, khiến toàn thành cùng bầu trời đêm rung động.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0599"]}]};
